(function(root){'use strict';const C=Critters,R=CritterRenderer.prototype,portrait=C.drawHeroPortrait,worm=R.worm,weapon=R.weapon,projectile=R.projectile,event=R.event,effects=R.effects,decor=R.decorations;
function gear(k,id,t=0){k.save();k.lineWidth=2;k.strokeStyle='#4a6179';if(id==='polar'){k.strokeStyle='#658ea6';k.lineWidth=10;k.beginPath();k.arc(0,-2,21,Math.PI,Math.PI*2);k.stroke();k.fillStyle='#efbc72';k.beginPath();k.moveTo(12,4);k.lineTo(26,8);k.lineTo(12,12);k.fill();}if(id==='bee'){k.strokeStyle='#72604c';k.lineWidth=2;for(const s of [-1,1]){k.beginPath();k.moveTo(s*8,-12);k.lineTo(s*14,-29);k.stroke();k.fillStyle='#f4ce7c';k.beginPath();k.arc(s*14,-31,5,0,7);k.fill();k.stroke();}k.fillStyle='#fff9e6aa';k.beginPath();k.ellipse(-25,24,13,21,-.6,0,7);k.fill();k.stroke();k.strokeStyle='#8d734d';k.lineWidth=5;k.beginPath();k.moveTo(-4,23);k.lineTo(16,29);k.stroke();}if(id==='pirate'){k.fillStyle='#584d56';k.beginPath();k.moveTo(-28,-9);k.lineTo(-20,-29);k.lineTo(0,-18);k.lineTo(20,-29);k.lineTo(28,-9);k.closePath();k.fill();k.stroke();k.strokeStyle='#e8ce97';k.lineWidth=3;k.beginPath();k.moveTo(-24,-10);k.lineTo(24,-10);k.stroke();k.fillStyle='#f5e7bf';k.font='bold 12px sans-serif';k.textAlign='center';k.fillText('×',0,-14);k.fillStyle='#394454';k.beginPath();k.ellipse(-6,-2,7,6,0,0,7);k.fill();}if(id==='astral'){k.strokeStyle='#f1d98f';k.lineWidth=3;k.beginPath();k.ellipse(0,-30+Math.sin(t*3),17,5,-.1,0,7);k.stroke();k.fillStyle='#e6e2ffaa';for(const y of [19,34]){k.beginPath();k.ellipse(-27,y,15,10,-.5,0,7);k.fill();}k.fillStyle='#fff3be';k.beginPath();k.arc(20,-13,3,0,7);k.fill();}k.restore();}
C.drawHeroPortrait=function(k,h,w=160,height=110){portrait.call(this,k,h,w,height);if(['polar','bee','pirate','astral'].includes(h.id)){const s=Math.min(w/150,height/125);k.save();k.translate(w*.51+5*s,height*.68-39*s);k.scale(s,s);gear(k,h.id);k.restore();}};
R.worm=function(k,u,...args){worm.call(this,k,u,...args);if(['polar','bee','pirate','astral'].includes(u.character)){k.save();k.translate(u.x,u.y);k.rotate(u.groundTilt||0);const s=args[0]||1;k.scale((u.face||1)*s,s);k.translate(4,-25);gear(k,u.character,this.time);k.restore();}if(u.poisonTurns>0){k.save();k.fillStyle='#a9dc8a';k.font='bold 11px sans-serif';k.fillText('독 '+u.poisonTurns,u.x+20,u.y-43);k.restore();}};
function shell(k,id,age=0){const w=C.WEAPONS[id];k.strokeStyle='#3b5665';k.lineWidth=2;k.fillStyle=w.color;if(w.id==='disc'){k.beginPath();k.ellipse(0,0,20,7,-.2,0,7);k.fill();k.stroke();k.strokeStyle='#fff0b8';k.beginPath();k.ellipse(0,0,12,3,-.2,0,7);k.stroke();}else if(w.id==='gravity'){for(let i=0;i<3;i++){k.strokeStyle=i%2?'#ddcdff':'#9082c9';k.beginPath();k.ellipse(0,0,9+i*6,5+i*4,age*2+i,0,7);k.stroke();}k.fillStyle='#6666a1';k.beginPath();k.arc(0,0,8,0,7);k.fill();}else if(w.id==='beacon'){k.fillStyle='#9ad3aa';k.beginPath();k.arc(0,0,15,0,7);k.fill();k.stroke();k.fillStyle='#efffe8';k.fillRect(-3,-10,6,20);k.fillRect(-10,-3,20,6);}else {k.beginPath();k.ellipse(0,3,12,17,.4,0,7);k.fill();k.stroke();k.fillStyle='#d5edab';k.beginPath();k.ellipse(8,-13,11,5,-.5,0,7);k.fill();k.stroke();}}
R.weapon=function(k,id,x,y,s=1){if(id<22)return weapon.call(this,k,id,x,y,s);k.save();k.translate(x,y);k.scale(s,s);shell(k,id);k.restore();};
R.projectile=function(k){const g=this.game,main=g.projectile,salvos=g.salvos||[],extra=[main,...salvos].filter(p=>p&&p.weapon>=22);g.projectile=main&&main.weapon<22?main:null;g.salvos=salvos.filter(p=>p.weapon<22);try{projectile.call(this,k);}finally{g.projectile=main;g.salvos=salvos;}for(const p of extra){if(this.drawProjectileSprite?.(k,p))continue;k.save();k.strokeStyle=C.WEAPONS[p.weapon].color;k.lineWidth=3;k.globalAlpha=.5;k.beginPath();(p.trail||[]).forEach((v,i)=>i?k.lineTo(v.x,v.y):k.moveTo(v.x,v.y));k.stroke();k.globalAlpha=1;k.translate(p.x,p.y);k.rotate(p.age*5);shell(k,p.weapon,p.age);k.restore();}};
R.event=function(e){const w=e.weapon!==undefined?C.WEAPONS[e.weapon]:null;if(e.type==='explosion'&&w?.kind==='beacon'){this.rings.push({x:e.x,y:e.y,r:150,life:.7,max:.7});for(let i=0;i<25;i++)this.fx.push({x:e.x+(i%5-2)*20,y:e.y+Math.floor(i/5)*5,vx:0,vy:-40,life:.8,max:.8,size:4,color:'#b0e5b2',type:'heal'});}else event.call(this,e);if(e.type==='explosion'&&w?.kind==='gravity')this.gravityVortex={x:e.x,y:e.y,life:.8};if(e.type==='rescue'){this.rings.push({x:e.x,y:e.y,r:80,life:.7,max:.7});this.texts.push({x:e.x,y:e.y-65,text:'별빛 구조!',life:1.3,color:'#d8c5ff'});root.PCSound?.tone(770,.4,'triangle');}};
R.effects=function(k,dt){effects.call(this,k,dt);const v=this.gravityVortex;if(v){if(!this.game.paused)v.life-=dt;if(v.life<=0){this.gravityVortex=null;return;}k.save();k.strokeStyle='#d5c5ff';k.globalAlpha=v.life;k.lineWidth=3;for(let i=0;i<5;i++){k.beginPath();for(let j=0;j<35;j++){const a=i*1.26+j*.1+this.time*6,r=j*2.5;const x=v.x+Math.cos(a)*r,y=v.y+Math.sin(a)*r;j?k.lineTo(x,y):k.moveTo(x,y);}k.stroke();}k.restore();}};
R.decorations=function(k,back){decor.call(this,k,back);const id=this.game.options.layout;if(back||!Number.isInteger(id)||id<12)return;for(const x of [130,420,690,930,1200,1450]){const y=this.game.heights[x];if(y>=this.game.water||!this.game.solid(x,y+3))continue;k.save();k.translate(x,y);if(id===12||id===15){k.strokeStyle='#9d8c6f';k.lineWidth=7;k.beginPath();k.arc(0,-24,22,0,7);k.stroke();k.lineWidth=4;const t=this.reduced?0:this.time;for(let i=0;i<8;i++){const a=i*Math.PI/4+t*.3;k.beginPath();k.moveTo(Math.cos(a)*8,-24+Math.sin(a)*8);k.lineTo(Math.cos(a)*28,-24+Math.sin(a)*28);k.stroke();}}else if(id===13||id===18){k.fillStyle=id===13?'#bfd4ef':'#c1cbd7';k.strokeStyle='#73899e';k.beginPath();k.moveTo(-20,0);k.lineTo(-7,-70);k.lineTo(4,-25);k.lineTo(16,-54);k.lineTo(27,0);k.fill();k.stroke();}else if(id===16){k.strokeStyle='#ddada7';k.lineCap='round';k.lineWidth=8;k.beginPath();k.moveTo(0,0);k.lineTo(0,-44);k.moveTo(0,-19);k.lineTo(-18,-31);k.moveTo(0,-28);k.lineTo(20,-38);k.stroke();}else if(id===17){k.fillStyle='#bdced7';k.fillRect(-22,-20,44,20);k.strokeStyle='#e7e6e5';k.lineWidth=3;k.beginPath();k.arc(0,-20,25,Math.PI,Math.PI*2);k.stroke();k.fillStyle='#9ad5d9';k.fillRect(-12,-13,24,8);}else {k.strokeStyle=id===14?'#91b89c':'#b8abd9';k.lineWidth=4;k.beginPath();k.moveTo(0,0);k.lineTo(0,-50);k.stroke();k.fillStyle=id===14?'#b7d4a3':'#dbcaed';for(let i=0;i<5;i++){const a=i*Math.PI*.4;k.beginPath();k.ellipse(Math.cos(a)*11,-50+Math.sin(a)*11,12,7,a,0,7);k.fill();}}k.restore();}};
const fire=PCSound.fire.bind(PCSound);PCSound.fire=function(id){if(id<22)return fire(id);this.tone(id===22?620:id===23?110:id===24?880:340,.25,id===23?'sine':'triangle',.1);};window.dispatchEvent(new Event('pc:wallet-changed'));
})(globalThis);
